struct charset_cache * nfscmd_findmap ( struct exportinfo * exi , struct sockaddr * sp ) { struct charset_cache * charset ; ASSERT ( exi != NULL ) ; ASSERT ( sp != NULL ) ; mutex_enter ( & exi -> exi_lock ) ; if ( ! ( exi -> exi_export . ex_flags & EX_CHARMAP ) ) { mutex_exit ( & exi -> exi_lock ) ; return ( NULL ) ; } for ( charset = exi -> exi_charset ; charset != NULL ; charset = charset -> next ) { if ( bcmp ( sp , & charset -> client_addr , sizeof ( sockaddr ) ) == 0 ) { break ; } } mutex_exit ( & exi -> exi_lock ) ; if ( charset == NULL ) { charset = nfscmd_charmap ( exi , sp ) ; } return ( charset ) ; } 